import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;

public final class Solution {
    private static final Map<String, String> DATA = new TreeMap<>();
    private Solution() {}

    public static synchronized boolean write(String key, String value) {
        if (!validKey(key) || value == null || value.length() > 256) return false;
        DATA.put(key, value);
        return true;
    }

    public static synchronized String read(String key) {
        return validKey(key) ? DATA.get(key) : null;
    }

    public static synchronized String[] snapshot() {
        String[] result = new String[DATA.size()];
        int i = 0;
        for (Map.Entry<String, String> entry : DATA.entrySet())
            result[i++] = entry.getKey() + "=" + entry.getValue();
        Arrays.sort(result);
        return result;
    }

    public static synchronized void clear() { DATA.clear(); }

    private static boolean validKey(String key) {
        if (key == null || key.length() < 1 || key.length() > 32) return false;
        for (int i = 0; i < key.length(); i++) {
            char c = key.charAt(i);
            if (!(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9')) return false;
        }
        return true;
    }
}
